  "por": "por",
  "La GTS es un banco online de futbolistas: dejas una copia repetida pidiendo otro futbolista a cambio, y cualquiera que tenga el que pides puede cambiártelo aunque no estés conectado.": "A GTS é um banco online de jogadores: você deixa uma cópia repetida pedindo outro jogador em troca, e qualquer um que tenha o que você pede pode trocar com você mesmo que você não esteja conectado.",
