  "Mejora la «Ventanilla GTS» en Mejoras": "Melhore o «Guichê GTS» em Melhorias",
  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Vagas: {openLength}/{slots}. A cópia que você deixa vai sem treino, estrelas nem ascensão: seu jogador fica com tudo. Um HERÓI ascendido pode sim deixar suas cópias repetidas. Não é possível deixar Lenda nem jogadores de evento, nem repetir uma troca.",
