  "Cuenta online": "Conta online",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "O serviço online não está ativado nesta versão. Seu progresso fica salvo neste navegador (Configurações » Exportar/Importar para levá-lo a outro). Com o serviço ativo, você poderá entrar com o Google, reservar seu nome no mundo todo, aparecer no ranking global e salvar na nuvem.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "Você está jogando como convidado: seu progresso fica salvo só neste navegador. Entre com o Google para reservar seu nome no mundo todo, aparecer no ranking e salvar na nuvem. Seu e-mail é privado: nunca aparece no ranking.",
