  "Tienes <b>5 equipos</b>: cambia entre ellos arriba. Elige <b>7 candidatos</b>. Empiezas solo con el <b>capitán</b>; al subir de nivel podrás fichar a los otros seis (máximo {MAX_TEAM} en el campo). Pulsa un futbolista de tu colección para añadirlo o quitarlo, pulsa una plaza para cambiarla, o arrastra para colocar e intercambiar. Se guarda solo.": "Você tem <b>5 times</b>: troque entre eles em cima. Escolha <b>7 candidatos</b>. Você começa só com o <b>capitão</b>; ao subir de nível poderá contratar os outros seis (máximo {MAX_TEAM} em campo). Toque em um jogador da sua coleção para adicioná-lo ou removê-lo, toque em uma vaga para trocá-la, ou arraste para posicionar e trocar. Salva sozinho.",
