  "Cada ficha suma 1 punto a la estadística que elijas (máximo {tmax} para este futbolista). Se ganan con victorias, rangos superados, supervivencia infinita, misiones semanales y logros.": "Cada ficha soma 1 ponto ao atributo que você escolher (máximo {tmax} para este jogador). São ganhas com vitórias, ranks superados, sobrevivência infinita, missões semanais e conquistas.",
