  "{add} Aura": "{add} Aura",
  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Valores centrados em 60: acima somam, abaixo subtraem. Cada técnica usa os atributos do seu jogador. O próprio chega a 99; com uma Aura, até {EFFECTIVE_STAT_MAX}.",
