  "NUEVO": "NOVO",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": ": é desbloqueado para sempre e já pode ir para o Meu Time.",
  "Duplicado": "Duplicata",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": ": serve para ascender o jogador; se ele não puder mais ascender, vira moedas.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "As duplicatas também pagam a <b>ascensão</b> de qualquer jogador (Fix 1.53): cada ascensão sobe uma raridade e custa conforme a raridade de onde sobe (Comum {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Lendário {ascenso4}). Ao chegar a Mítico, o HERÓI custa conforme a raridade com que nasceu: Comum {heroe}, Raro {heroe2}, Épico {heroe3}, Lendário {heroe4}, Mítico {heroe5} e Lenda {heroe6}. Depois, cada HERÓI ganha até {HERO_STARS_MAX} estrelas de herói (Mítico {estrella} duplicatas cada).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "Com {MAX_STARS} estrelas e HERÓI, cada cópia dá moedas (de {comun} a {leyenda} conforme a raridade).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Fichas = máquina de cápsulas · Moedas = melhorias e lojas. Gráficos da máquina: Inazuma Eleven 3 (folha do The Spriters Resource, extraída por Avegaille), recurso local.",
  "Duplicado · +{refund} monedas": "Duplicata · +{refund} moedas",
