  "REPERTORIO": "REPERTÓRIO",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Cada jogador só usa o próprio repertório. Aqui você desbloqueia as técnicas dele e compra <b>manuais</b> de dano permanente (subir o nível de uma técnica na partida é à parte).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Bônus para todo o time. Não mudam o uniforme do Raimon que aparece em combate.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Projeto de fãs não oficial",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors é um fangame independente e gratuito desenvolvido por AstraStorm17, inspirado na franquia Inazuma Eleven.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, seus personagens, nomes, designs, logotipos, música e materiais originais são propriedade da LEVEL-5 e/ou de seus respectivos titulares.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "Este projeto não é afiliado, patrocinado nem aprovado pela LEVEL-5.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "O código e os materiais originais desenvolvidos especificamente para o InaZurvivors pertencem a seus respectivos autores.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Os recursos gráficos e sonoros de terceiros mantêm seus direitos originais.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "A inclusão de créditos e deste aviso não implica a existência de uma licença ou autorização para distribuir material protegido.",
  "Desarrollo": "Desenvolvimento",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Design, direção e desenvolvimento: AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programação com a assistência do Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Recursos de terceiros e sua procedência",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Jogadores, retratos, corpos, escudos, objetos, arenas e música: Inazuma Eleven 2 (LEVEL-5), extraídos de uma cópia própria do jogo.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Jogadores, retratos e escudos das sagas Mundial, GO, Chrono Stones, Galaxy, Ares e Orion: Inazuma Eleven 3 (LEVEL-5) com o patch de fãs «Great Road of Heroes 3.1». Autoria do patch: não verificada; a base e os acréscimos do patch não podem ser separados.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Criados para o InaZurvivors: efeitos de supertécnicas, efeitos sonoros, ícones de elemento, orbes, música «Gerada» e interface.",
  "Redes sociales": "Redes sociais",
  "Sobre el desarrollador": "Sobre o desenvolvedor",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm também criou outros videogames.",
  "Enlaces oficiales": "Links oficiais",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Sem conta, o InaZurvivors não coleta dados pessoais: seu progresso fica salvo só neste navegador. Com conta online (Google), são salvos seu e-mail do Google (privado), seu nome, suas marcas e seu salvamento.",
