  "Sin vínculo especial con {pName}. Un compañero de historia, familia o técnica conjunta daría {x1}%.": "Sem vínculo especial com {pName}. Um companheiro de história, família ou técnica conjunta daria {x1}%.",
  "Bonificación = estadística del Aura × {x1}%, redondeada. Lo propio sigue en 99 como máximo; con el Aura, hasta {EFFECTIVE_STAT_MAX}.": "Bônus = atributo da Aura × {x1}%, arredondado. O próprio continua em 99 no máximo; com a Aura, até {EFFECTIVE_STAT_MAX}.",
  "{x1} · {x2} · poder {power}": "{x1} · {x2} · poder {power}",
  "La primera empieza la partida en una ranura extra de Aura; la segunda puede aprenderse al subir de nivel. Golpean al {x1}% (son una técnica activa de más). No sustituyen a las suyas y desaparecen si quitas el Aura.": "A primeira começa a partida em um espaço extra de Aura; a segunda pode ser aprendida ao subir de nível. Acertam a {x1}% (são uma técnica ativa a mais). Não substituem as dele e somem se você remover a Aura.",
  "{x1} Afinidad de {x2}": "{x1} Afinidade de {x2}",
  "Las técnicas de {pName} de elemento {x1} (también las heredadas) hacen <b>+{x2}%</b> de daño. {pName} sigue siendo de {x3} para todo lo demás.": "As técnicas de {pName} do elemento {x1} (também as herdadas) causam <b>+{x2}%</b> de dano. {pName} continua sendo de {x3} para todo o resto.",
