  "{x1} ◉ la tirada · Míticos al 3%": "{x1} ◉ o giro · Míticos a 3%",
  "DÍA {x1}{x2}": "DIA {x1}{x2}",
  "{x1} Si te saltas días no pierdes nada: el pase te espera.": "{x1} Se pular dias, você não perde nada: o passe te espera.",
  "{x1}{x2} · tras el día {PASSLength} empieza un ciclo nuevo": "{x1}{x2} · depois do dia {PASSLength} começa um ciclo novo",
  "{x1} <b>{x2}</b>, y si llevas {min} o más jugadores de ese equipo en el campo, «Química de club»: +{x3}% de daño.": "{x1} <b>{x2}</b>, e se você tiver {min} ou mais jogadores desse time em campo, «Química de clube»: +{x3}% de dano.",
  "Posiciones distintas ({x1} / {x2}): la comparación es orientativa.": "Posições diferentes ({x1} / {x2}): a comparação é aproximada.",
