  "Faltan duplicados: {x1} más": "Faltam duplicatas: mais {x1}",
  "Faltan {x1} monedas": "Faltam {x1} moedas",
  "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · daño ×{toFixed} · vida ×{toFixed2} · duplicados libres {sparesOf}": "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · dano ×{toFixed} · vida ×{toFixed2} · duplicatas livres {sparesOf}",
  "✦ Elige {x1} de límite (+{STAR_CAP_STEP})": "✦ Escolha {x1} de limite (+{STAR_CAP_STEP})",
  "Toca una estadística por cada estrella: su límite sube +{STAR_CAP_STEP}. Puedes repetir la misma.{x1}": "Toque em um atributo para cada estrela: o limite dele sobe +{STAR_CAP_STEP}. Você pode repetir o mesmo.{x1}",
  "{pName}: {done} {x1} de límite": "{pName}: {done} {x1} de limite",
  "★ Estrella de héroe ({sparesOf}/{x1})": "★ Estrela de herói ({sparesOf}/{x1})",
  "▲ Ascensión ({sparesOf}/{x1})": "▲ Ascensão ({sparesOf}/{x1})",
  "Maestría {x1}/{MASTERY_USESLength} · +{x2}% daño · {x3} usos": "Maestria {x1}/{MASTERY_USESLength} · +{x2}% de dano · {x3} usos",
  "Estadísticas · media {statMean}{x1}": "Atributos · média {statMean}{x1}",
