  "COLABORACIÓN · TERMINA EN {x1}": "COLABORAÇÃO · TERMINA EM {x1}",
  "★ Destacada hoy: Épico ×{x1} · Legendario, Mítico y Leyenda ×{x2}": "★ Destaque de hoje: Épico ×{x1} · Lendário, Mítico e Lenda ×{x2}",
  "{x1}Precio y reglas": "{x1}Preço e regras",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "Os jogadores especiais só saem aqui, com {x1} Comuns, Raros e Épicos de preenchimento. É pago com fichas de evento: cada partida no Rank S ou X te dá tantas quanto fichas normais enquanto o evento durar.",
  "{x1}Tus {unit}": "{x1}Suas {unit}",
  "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (diez ×10 de golpe, un Épico o mejor asegurado en cada diez). {x4}{x5}": "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (dez ×10 de uma vez, um Épico ou melhor garantido a cada dez). {x4}{x5}",
  "Te llega para {x1} tirada(s).": "Dá para {x1} giro(s).",
  "{x1}Cómo conseguir fichas": "{x1}Como conseguir fichas",
  "{x1}Nuevo, duplicado y ascensión": "{x1}Novo, duplicata e ascensão",
  "(hasta {MAX_STARS}): se compran con monedas en su ficha (10.000, 20.000… 50.000). Cada una da +{x1}% daño, +{x2}% vida y +5 al límite de la estadística que elijas. Los HÉROES y Campeones tienen 3 estrellas extra (100.000, 110.000 y 120.000).": "(até {MAX_STARS}): são compradas com moedas na ficha dele (10.000, 20.000… 50.000). Cada uma dá +{x1}% de dano, +{x2}% de vida e +5 no limite do atributo que você escolher. Os HERÓIS e Campeões têm 3 estrelas extras (100.000, 110.000 e 120.000).",
  "{x1}Probabilidades": "{x1}Probabilidades",
  "{x1}: sin futbolistas por ahora; su probabilidad pasa a la rareza inferior.": "{x1}: sem jogadores por enquanto; a probabilidade passa para a raridade inferior.",
