  "{x1} · {techniquesLength} técnicas": "{x1} · {techniquesLength} técnicas",
  "Máquina de cápsulas: gráficos de Inazuma Eleven 3 (LEVEL-5), hoja publicada en {x1}, ripeada por Avegaille.": "Máquina de cápsulas: gráficos do Inazuma Eleven 3 (LEVEL-5), folha publicada no {x1}, extraída por Avegaille.",
  "Nombres en español e inglés de parte de las técnicas: {x1} (Fandom), contenido bajo {x2}.": "Nomes em espanhol e inglês de parte das técnicas: {x1} (Fandom), conteúdo sob {x2}.",
  "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Herramienta: {x3} (MIT).": "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Ferramenta: {x3} (MIT).",
  "Fuente: Press Start 2P © The Press Start 2P Project Authors ({x1}), vía Fontsource.": "Fonte: Press Start 2P © The Press Start 2P Project Authors ({x1}), via Fontsource.",
  "Ahora suena: {x1}. Por defecto suena la música de Inazuma Eleven exportada de tu copia. «Generada» usa temas creados para este proyecto.": "Tocando agora: {x1}. Por padrão toca a música do Inazuma Eleven exportada da sua cópia. «Gerada» usa temas criados para este projeto.",
