  "Ver el Sector": "Ver o Setor",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "O futebol precisa de ordem. A partir de hoje, o Quinto Setor decide como cada jogo é jogado.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Junte-se a nós… ou tente resistir. Toda semana veremos qual lado joga melhor.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Bem-vindo ao Quinto Setor. Aqui o futebol se joga do jeito que eu digo.",
  "Acata mis decretos y tu bando ganará.": "Obedeça aos meus decretos e seu lado vencerá.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "A Resistência… Vamos ver quanto o vento de vocês aguenta.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Rebele-se se quiser: o Quinto Setor também sabe jogar duro.",
  "¡Llega {eName}!": "Chegou {eName}!",
  "{x1} · {x2} rivales · Nv {level}": "{x1} · {x2} rivais · Nv {level}",
  "sus estadísticas (Aura legendaria)": "seus atributos (Aura lendária)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Cada vaga do seu time agora tem uma <b>{x1}</b> {x2} <b>{x3}</b>. Ali você coloca outro jogador da sua coleção para apoiar o da vaga. A Aura não joga: ela o potencializa.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Só podem ser Aura os <b>Lendários, Míticos e Lendas</b>.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "Uma por jogador. Nada é gasto: sua coleção não muda.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "A Aura soma <b>{x1}%</b> {x2} <b>{x3}</b> aos mesmos do portador.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Exemplo: Chute 90 + Aura com Chute 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "O próprio continua em 99 no máximo; com a Aura, até <b>120</b>, e no combate dá para sentir.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "No radar, o que a Aura dá aparece em <b style=\"color:#7ff6ff\">ciano</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "Se os dois têm história (técnica conjunta, amizade, família ou rivalidade), a Aura dá <b>{x1}%</b>{x2} <b>♥</b>.",
  "Axel y Shawn, Mark y Nathan, Jude y Celia, Arion y Riccardo...": "Axel e Shawn, Mark e Nathan, Jude e Celia, Arion e Riccardo...",
  "Estar en el mismo equipo no basta.": "Estar no mesmo time não basta.",
  "El portador hereda <b>{x1}</b> del Aura: una empieza la partida en una ranura extra y la otra llega como carta al subir de nivel. No sustituyen a las suyas.": "O portador herda <b>{x1}</b> da Aura: uma começa a partida em um espaço extra e a outra chega como carta ao subir de nível. Não substituem as dele.",
  "Sus técnicas del elemento del Aura hacen <b>+{x1}%</b>.": "As técnicas dele do elemento da Aura causam <b>+{x1}%</b>.",
  "Con el Aura puede lanzar <b>{x1}</b>: Axel con Shawn de Aura, Fuego cruzado.": "Com a Aura ele pode lançar <b>{x1}</b>: Axel com Shawn de Aura, Fogo Cruzado.",
  "Cómo equiparla:": "Como equipá-la:",
  "toca «+ AURA» y elige en tu colección, o arrastra la carta encima.": "toque em «+ AURA» e escolha na sua coleção, ou arraste a carta por cima.",
