  "Estrella de héroe {x1} de {HERO_STARS_MAX}: +{x2}% daño, +{x3}% vida y +1 a todas sus estadísticas": "Estrela de herói {x1} de {HERO_STARS_MAX}: +{x2}% de dano, +{x3}% de vida e +1 em todos os atributos",
