  "LA GACETA {x1}": "A GAZETA {x1}",
  "Versión de pruebas del cooperativo: puede fallar. Tu partida es la misma que en la web normal.": "Versão de testes do cooperativo: pode falhar. Seu jogo salvo é o mesmo da web normal.",
  "PRUEBAS · pre-2.0": "TESTES · pré-2.0",
  "Cargando futbolistas…": "Carregando jogadores…",
  "No se pudieron cargar los datos del juego. Si el problema sigue, esta versión puede no incluir sus recursos.": "Não foi possível carregar os dados do jogo. Se o problema continuar, esta versão pode não incluir seus recursos.",
  "Preparando caras y objetos…": "Preparando rostos e objetos…",
  "Abriendo el vestuario…": "Abrindo o vestiário…",
  "¡Listo!": "Pronto!",
  "InaZurvivors 2.3 — Ya en inglés": "InaZurvivors 2.3 — Agora em inglês",
  "InaZurvivors, now in English": "InaZurvivors, now in English",
  "El juego entero se puede jugar en inglés: menús, partidas, datos, noticias y todo el historial de versiones. Si tu navegador está en inglés se abre solo en inglés; si no, sigue en español.": "O jogo inteiro pode ser jogado em inglês: menus, partidas, dados, notícias e todo o histórico de versões. Se seu navegador estiver em inglês, ele abre direto em inglês; se não, continua em espanhol.",
  "Español o inglés": "Espanhol ou inglês",
  "Elige el idioma en Ajustes > Idioma, o déjalo en «Automático» para que siga al navegador. Al cambiarlo, el juego se recarga en el idioma nuevo y tu partida no cambia.": "Escolha o idioma em Configurações > Idioma, ou deixe em «Automático» para seguir o navegador. Ao mudar, o jogo recarrega no idioma novo e seu jogo salvo não muda.",
  "Nombres oficiales": "Nomes oficiais",
  "En inglés, las supertécnicas y las técnicas combinadas llevan su nombre del doblaje oficial (Fire Tornado, God Hand, Crossfire…), y los elementos son Fire, Wind, Wood y Earth.": "Em inglês, as supertécnicas e as técnicas combinadas têm seu nome da dublagem oficial (Fire Tornado, God Hand, Crossfire…), e os elementos são Fire, Wind, Wood e Earth.",
  "Noticias en los dos idiomas": "Notícias nos dois idiomas",
  "Las noticias y todas las versiones desde la v1.0 se pueden leer en inglés.": "As notícias e todas as versões desde a v1.0 podem ser lidas em inglês.",
  "Números a su manera": "Números do jeito deles",
  "En inglés, las cifras y las fechas salen con el formato inglés (1,000 monedas, 0.5 %).": "Em inglês, os números e as datas aparecem no formato inglês (1,000 moedas, 0.5 %).",
  "Abre Ajustes y mira la nueva opción Idioma.": "Abra Configurações e veja a nova opção Idioma.",
  "Pásale el juego a tus amigos que no hablan español.": "Passe o jogo para seus amigos que não falam espanhol.",
  "Muévete con el joystick y acércate a alguien para ver su ficha; tócala para abrir su perfil.": "Mova-se com o joystick e chegue perto de alguém para ver a ficha dele; toque nela para abrir o perfil.",
  "Muévete con WASD o flechas y pasa el ratón por encima de alguien para ver su ficha; haz clic para abrir su perfil.": "Mova-se com WASD ou setas e passe o mouse sobre alguém para ver a ficha dele; clique para abrir o perfil.",
  "Top 3": "Top 3",
  "♥ AMIGO": "♥ AMIGO",
  "Equipación: {x1}": "Uniforme: {x1}",
  "Toca para ver su perfil": "Toque para ver o perfil",
  "Clic para ver su perfil": "Clique para ver o perfil",
  "Sala de jugadores renovada": "Sala de jogadores renovada",
  "Cada jugador lleva su equipación, tus amigos salen en verde, el top 3 con su corona y, sobre el nombre, el escudo de su clan y su bando. Haz clic (o toca su ficha) para abrir su perfil.": "Cada jogador usa seu uniforme, seus amigos aparecem em verde, o top 3 com sua coroa e, sobre o nome, o escudo do seu clã e seu lado. Clique (ou toque na ficha) para abrir o perfil.",
  "¿Padre e hijo? Jaden lleva el apellido de Mark adulto y juega con su mismo corazón. Nadie lo ha confirmado.": "Pai e filho? Jaden tem o sobrenome do Mark adulto e joga com o mesmo coração. Ninguém confirmou.",
  "Los Evans: el cuaderno de entrenamiento de David llega hasta Jaden.": "Os Evans: o caderno de treino de David chega até Jaden.",
  "Silvia lo cuida como cuidó al Raimon de Mark… y dicen que Jaden tiene su misma mirada. ¿Será su madre?": "Silvia cuida dele como cuidou do Raimon de Mark… e dizem que Jaden tem o mesmo olhar dela. Será a mãe dele?",
  "Vibración (móvil)": "Vibração (celular)",
  "Activada": "Ativada",
  "Desactivada": "Desativada",
  "Más vivo en el móvil": "Mais vivo no celular",
  "El móvil vibra al recibir un golpe, al subir de nivel, con las definitivas, al llegar el jefe y al fichar un Legendario o mejor (se quita en Ajustes). Los botones responden al tocarlos y los avisos ya no tapan la partida.": "O celular vibra ao receber um golpe, ao subir de nível, com as definitivas, quando o chefe chega e ao contratar um Lendário ou melhor (dá para desativar em Configurações). Os botões respondem ao toque e os avisos não cobrem mais a partida.",
  "la Llave dorada del pase": "a Chave dourada do passe",
  "{n} futbolistas": "{n} jogadores",
  "Creadores de contenido: banner y marco propios, 1.500 fichas de colaboración, 3.000 fichas, la Llave dorada, los 7 del Banner de agradecimiento, 300.000 monedas y 9 Fichas EG": "Criadores de conteúdo: banner e moldura próprios, 1.500 fichas de colaboração, 3.000 fichas, a Chave dourada, os 7 do Banner de agradecimento, 300.000 moedas e 9 Fichas EG",
  "Creador de contenido": "Criador de conteúdo",
  "Código de creadores de contenido": "Código de criadores de conteúdo",
  "Grabas, editas y subes: InaZurvivors llega más lejos gracias a ti.": "Você grava, edita e posta: InaZurvivors chega mais longe graças a você.",
  "Marco de Creador": "Moldura de Criador",
  "Un botón de play con alas: el marco de quien graba InaZurvivors.": "Um botão de play com asas: a moldura de quem grava InaZurvivors.",
  "Tu última partida se cortó a los {x1}: aquí tienes lo que llevabas ganado.": "Sua última partida foi cortada aos {x1}: aqui está o que você já tinha ganhado.",
  "Teclados AZERTY": "Teclados AZERTY",
  "El movimiento va por la posición de las teclas y no por la letra: en un teclado francés te mueves con ZQSD.": "O movimento segue a posição das teclas e não a letra: em um teclado francês você se move com ZQSD.",
  "¡RÉCORD!": "RECORDE!",
  "Eliminaciones": "Eliminações",
  "Nivel": "Nível",
