  "Falta {missingLength}": "Falta {missingLength}",
  "1 compañero de {captainElement} con el capitán: +{x2}% cada uno": "1 companheiro de {captainElement} com o capitão: +{x2}% cada",
  "{allies} compañeros de {captainElement} con el capitán: +{x2}% cada uno": "{allies} companheiros de {captainElement} com o capitão: +{x2}% cada",
  "1 miembro": "1 membro",
  "InaZurvivors 2.4 — Ya en francés, italiano y alemán": "InaZurvivors 2.4 — Agora em francês, italiano e alemão",
  "InaZurvivors, maintenant en français · ora in italiano · jetzt auf Deutsch": "InaZurvivors, maintenant en français · ora in italiano · jetzt auf Deutsch",
  "El juego entero se puede jugar en francés, en italiano y en alemán: menús, partidas, datos, noticias y todo el historial de versiones. Si tu navegador está en uno de esos idiomas, se abre solo en él.": "O jogo inteiro pode ser jogado em francês, italiano e alemão: menus, partidas, dados, notícias e todo o histórico de versões. Se seu navegador estiver em um desses idiomas, ele abre direto nele.",
  "Cinco idiomas": "Cinco idiomas",
  "Elige el idioma en Ajustes > Idioma (español, inglés, francés, italiano o alemán), o déjalo en «Automático» para que siga al navegador. Al cambiarlo, el juego se recarga y tu partida no cambia.": "Escolha o idioma em Configurações > Idioma (espanhol, inglês, francês, italiano ou alemão), ou deixe em «Automático» para seguir o navegador. Ao mudar, o jogo recarrega e seu jogo salvo não muda.",
  "Las supertécnicas, las combinadas y los talentos llevan su nombre oficial de los juegos y el anime de cada idioma: Tornade de Feu y Main Céleste en francés, Tornado di Fuoco y Mano di Luce en italiano, Feuertornado y Himmelshand en alemán. Los elementos son Feu, Air, Bois y Terre en francés, Fuoco, Vento, Foresta y Montagna en italiano, y Feuer, Wind, Holz y Erde en alemán.": "As supertécnicas, as combinadas e os talentos têm seu nome oficial dos jogos e do anime de cada idioma: Tornade de Feu e Main Céleste em francês, Tornado di Fuoco e Mano di Luce em italiano, Feuertornado e Himmelshand em alemão. Os elementos são Feu, Air, Bois e Terre em francês, Fuoco, Vento, Foresta e Montagna em italiano, e Feuer, Wind, Holz e Erde em alemão.",
  "Cifras y fechas en el formato de cada idioma: 1 000 en francés, 1.000 en italiano y en alemán.": "Números e datas no formato de cada idioma: 1 000 em francês, 1.000 em italiano e em alemão.",
  "Pásale el juego a tus amigos de Francia, Italia y Alemania.": "Passe o jogo para seus amigos da França, da Itália e da Alemanha.",
  "Más juegos de AstraStorm": "Mais jogos de AstraStorm",
  "En la barra de arriba del menú y en Créditos, el botón de itch.io lleva a la página de AstraStorm, el creador, con sus otros juegos. Si quieres apoyar sus próximos proyectos, ahí lo tienes.": "Na barra de cima do menu e em Créditos, o botão do itch.io leva à página de AstraStorm, o criador, com seus outros jogos. Se quiser apoiar os próximos projetos dele, é por ali.",
  "CINCO IDIOMAS": "CINCO IDIOMAS",
  "Avatar": "Avatar",
  "Confirmar": "Confirmar",
  "Válido": "Válido",
  "Comprobando…": "Verificando…",
