  "Ocupado": "Em uso",
  "InaZurvivors 2.5 — Ya en catalán y portugués": "InaZurvivors 2.5 — Agora em catalão e português",
  "InaZurvivors, ara en català · agora em português": "InaZurvivors, ara en català · agora em português",
  "El juego entero se puede jugar en catalán y en portugués de Brasil: menús, partidas, datos, noticias y todo el historial de versiones. Si tu navegador está en uno de esos idiomas, se abre solo en él.": "O jogo inteiro pode ser jogado em catalão e em português do Brasil: menus, partidas, dados, notícias e todo o histórico de versões. Se o seu navegador estiver em um desses idiomas, ele abre direto nele.",
  "Siete idiomas": "Sete idiomas",
  "SIETE IDIOMAS": "SETE IDIOMAS",
  "Elige el idioma en Ajustes > Idioma (español, inglés, francés, italiano, alemán, catalán o portugués), o déjalo en «Automático» para que siga al navegador. Al cambiarlo, el juego se recarga y tu partida no cambia.": "Escolha o idioma em Configurações > Idioma (espanhol, inglês, francês, italiano, alemão, catalão ou português), ou deixe em «Automático» para seguir o navegador. Ao mudar, o jogo recarrega e seu jogo salvo não muda.",
  "Las supertécnicas llevan el nombre del doblaje de cada idioma cuando existe: Tornado de Foc y Mà Celestial en catalán, como en el Super3; Furacão de Fogo y Mão Fantasma en portugués, como en Super Onze. Los elementos son Foc, Aire, Bosc y Muntanya en catalán, y Fogo, Vento, Floresta y Montanha en portugués.": "As supertécnicas têm o nome da dublagem de cada idioma quando existe: Tornado de Foc e Mà Celestial em catalão, como no Super3; Furacão de Fogo e Mão Fantasma em português, como em Super Onze. Os elementos são Foc, Aire, Bosc e Muntanya em catalão, e Fogo, Vento, Floresta e Montanha em português.",
  "Registro en tu idioma": "Cadastro no seu idioma",
  "Los pasos del registro y la comprobación del nombre ya salen en tu idioma, también en inglés, francés, italiano y alemán.": "As etapas do cadastro e a verificação do nome agora aparecem no seu idioma, também em inglês, francês, italiano e alemão.",
  "Banderas en la presentación": "Bandeiras na apresentação",
  "Al abrir la versión nueva, las banderas de los siete idiomas giran alrededor del número.": "Ao abrir a versão nova, as bandeiras dos sete idiomas giram ao redor do número.",
  "Cifras y fechas en el formato de cada idioma: 1.000 en catalán y en portugués.": "Números e datas no formato de cada idioma: 1.000 em catalão e em português.",
